-- Catalogo Austria, versione 3 (AT-3).
-- GENERATO da scripts/seed-catalog.ts: non modificare a mano, rigenerare con `npx tsx scripts/seed-catalog.ts --country AT --version 3`.
-- Prerequisito: migrazioni supabase/migrations/20261106000100 … 20261106000500 e 20261110000100_foto_consigli.sql.
-- Contiene tutta la versione AT-2 (controllo finale: righe identiche per chiave) e la indica come versione precedente.
-- Idempotente: con la versione già pubblicata non scrive nulla e controlla solo i conteggi.
-- Tocca solo le tabelle del catalogo e la versione delle nazioni dei viaggi a righe; nessun dato di auth.
-- Dopo il controllo cancella le versioni precedenti della nazione (migrazione 20261119000000_cataloghi_superati.sql).

begin;

-- Prerequisiti: versione non superata, versione precedente pubblicata, tabelle dei traghetti presenti
do $pre$
begin
  if exists (select 1 from public.catalog_releases where country_code = 'AT' and status = 'pubblicata' and version > 3) then
    raise exception 'Il catalogo AT ha già una versione più recente di AT-3: questo seed è superato';
  end if;
  if not exists (select 1 from public.catalog_releases where release_id = 'AT-2' and status in ('pubblicata', 'ritirata'))
     and not exists (select 1 from public.catalog_releases where release_id = 'AT-3' and status = 'pubblicata') then
    raise exception 'La versione precedente AT-2 non è pubblicata: applicare prima il suo seed';
  end if;
  if to_regclass('public.place_photos') is null or to_regclass('public.place_tips') is null then
    raise exception 'Mancano le tabelle di foto e consigli: applicare prima supabase/migrations/20261110000100_foto_consigli.sql';
  end if;
end $pre$;

on conflict (code) do nothing;

on conflict (release_id) do nothing;

on conflict (place_key) do nothing;

-- Contenuto della versione: si scrive solo se è ancora in bozza
do $seed$
begin
  if not exists (select 1 from public.catalog_releases where release_id = 'AT-3' and status = 'bozza') then
    raise notice 'Versione AT-3 già pubblicata: nessuna scrittura, solo controllo';
    return;
  end if;




-- operators: nessuna riga

-- voyages: nessuna riga

-- route_ports: nessuna riga

-- place_links: nessuna riga


-- place_tips: nessuna riga

end $seed$;

update public.catalog_releases set status = 'pubblicata', published_at = now() where release_id = 'AT-3' and status = 'bozza';

-- Controllo finale: se fallisce, la transazione si annulla
do $check$
declare
  v_n bigint;
begin
  if not exists (select 1 from public.countries where code = 'AT' and currency = 'EUR' and timezone = 'Europe/Vienna' and language = 'de') then
    raise exception 'Nazione AT: valuta, fuso o lingua diversi da quelli del seed';
  end if;
  perform now() at time zone 'Europe/Vienna';
  if not exists (select 1 from public.catalog_releases where release_id = 'AT-3' and status = 'pubblicata') then
    raise exception 'Versione AT-3 non pubblicata';
  end if;
  select count(*) into v_n from public.regions where release_id = 'AT-3';
  if v_n <> 9 then raise exception 'regions (release_id = ''AT-3''): attese 9 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3';
  if v_n <> 320 then raise exception 'places (release_id = ''AT-3''): attese 320 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_texts where release_id = 'AT-3';
  if v_n <> 320 then raise exception 'place_texts (release_id = ''AT-3''): attese 320 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_sources where release_id = 'AT-3';
  if v_n <> 1493 then raise exception 'place_sources (release_id = ''AT-3''): attese 1493 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.operators where release_id = 'AT-3';
  if v_n <> 0 then raise exception 'operators (release_id = ''AT-3''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.voyages where release_id = 'AT-3';
  if v_n <> 0 then raise exception 'voyages (release_id = ''AT-3''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.route_ports where release_id = 'AT-3';
  if v_n <> 0 then raise exception 'route_ports (release_id = ''AT-3''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_links where release_id = 'AT-3';
  if v_n <> 0 then raise exception 'place_links (release_id = ''AT-3''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3' and category = 'porti';
  if v_n <> 0 then raise exception 'places (release_id = ''AT-3'' and category = ''porti''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3' and coords_status = 'verificate';
  if v_n <> 320 then raise exception 'places (release_id = ''AT-3'' and coords_status = ''verificate''): attese 320 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3' and official_url is not null;
  if v_n <> 212 then raise exception 'places (release_id = ''AT-3'' and official_url is not null): attese 212 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3' and wikidata_qid is not null;
  if v_n <> 320 then raise exception 'places (release_id = ''AT-3'' and wikidata_qid is not null): attese 320 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'AT-3' and base_place_key is not null;
  if v_n <> 0 then raise exception 'places (release_id = ''AT-3'' and base_place_key is not null): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_photos where release_id = 'AT-3';
  if v_n <> 310 then raise exception 'place_photos (release_id = ''AT-3''): attese 310 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_tips where release_id = 'AT-3';
  if v_n <> 0 then raise exception 'place_tips (release_id = ''AT-3''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.catalog_releases where release_id = 'AT-3' and previous_release_id = 'AT-2';
  if v_n <> 1 then raise exception 'catalog_releases (release_id = ''AT-3'' and previous_release_id = ''AT-2''): attese 1 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places p join public.place_keys k on k.place_key = p.place_key where p.release_id = 'AT-3' and k.country_code <> 'AT';
  if v_n <> 0 then raise exception 'Chiavi di luogo registrate per un''altra nazione: %', v_n; end if;
  select count(*) into v_n from public.places p where p.release_id = 'AT-3' and not exists (select 1 from public.place_texts t where t.release_id = p.release_id and t.place_key = p.place_key and t.lang = 'it');
  if v_n <> 0 then raise exception 'Luoghi senza testo italiano: %', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.regions x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.regions x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'regions: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.places x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.places x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'places: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_texts x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.place_texts x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'place_texts: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_sources x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.place_sources x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'place_sources: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.operators x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.operators x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'operators: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.voyages x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.voyages x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'voyages: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.route_ports x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.route_ports x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'route_ports: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_links x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.place_links x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'place_links: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_photos x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.place_photos x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'place_photos: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  select count(*) into v_n from (select to_jsonb(x) - 'release_id' from public.place_tips x where x.release_id = 'AT-2'
    except select to_jsonb(x) - 'release_id' from public.place_tips x where x.release_id = 'AT-3') d;
  if v_n <> 0 then raise exception 'place_tips: % righe di AT-2 mancano o sono diverse in AT-3 (la nuova versione deve contenere tutta la precedente)', v_n; end if;
  raise notice 'Catalogo AT-3 pubblicato e controllato: 320 luoghi, 0 crociere, 0 porti in rotta';
end $check$;

-- Versioni precedenti: cancellate (i viaggi passano a questa, che le contiene)
do $purge$
begin
  if to_regprocedure('private.purge_superseded_releases(text)') is not null then
    perform private.purge_superseded_releases('AT');
  end if;
end $purge$;

commit;
